<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigWelcomeEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWelcomeEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withWelcomeEmail,
 * getWelcomeEmail/welcomeEmail accessors, and isWelcomeEmailChanged with/without original.
 */
class TenantConfigWelcomeEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWelcomeEmail creates a new instance with the WelcomeEmail set
     * from a string value, and getWelcomeEmail returns the primitive string.
     */
    public function testWithWelcomeEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWelcomeEmailAccessorUnitTest();

        // Act
        $result = $holder->withWelcomeEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getWelcomeEmail());
    }
    /**
     * Asserts that withwelcomeEmail has access to the value object
     * from a string value, and getWelcomeEmail returns the primitive string.
     */
    public function testWithWelcomeEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWelcomeEmailAccessorUnitTest();

        // Act
        $result = $holder->withWelcomeEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->welcomeEmail()->value());
    }
    public function testChangedWelcomeEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWelcomeEmailAccessorUnitTest();
        $original = $holder->withWelcomeEmail('one');
        $same = $holder->withWelcomeEmail('one');
        $modified = $holder->withWelcomeEmail('other');

        // Act
        $unchanged = $holder->isWelcomeEmailChanged();
        $withSame = $original->isWelcomeEmailChanged($same);
        $withDiferent = $original->isWelcomeEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigWelcomeEmailAccessorUnitTest
{
    use TenantConfigWelcomeEmailAccessor;
}
